using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class PlanningShotLinkLifecycleWpfTests
{
    static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
    [TestMethod]public Task ShotOwnedCopySaveRecreateExportAndDifferentRootImportKeepCopyButNoMachineApproval()=>RunSta(async()=>
    {
        EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);await f.Vm.NewShotCommand.ExecuteAsync(null);var shot=(await f.Shots.LoadAsync(f.Id)).Shots.Single();var reference=new ProjectShotReference(Guid.NewGuid(),ShotReferenceKind.Pose,ExternalReference:Path.Combine(f.Root,"old-missing.png"),Title:"镜头独有副本参考");await f.Shots.SaveAsync(shot with{Name="副本闭环镜头",References=[reference]});await f.Vm.LoadAsync(f.Id);
        var output=Path.GetFullPath(Environment.GetEnvironmentVariable("KITAO_SHOT_LIFECYCLE_EVIDENCE")??Path.Combine(f.Root,"evidence"));Directory.CreateDirectory(output);var selected=Path.Combine(output,"selected-shot.png");await File.WriteAllBytesAsync(selected,PlanningRichFlowFixture.ReferencePng(0));var dialogs=new Decisions{File=selected,Accept=true};var vm=new PlanningCenterViewModel(f.Projects,f.Bookings,dialogs,f.Shots,f.Planning);await vm.LoadAsync(f.Id);await vm.LocateExternalAsync(vm.ExternalDependencies.Single(),true);Assert.HasCount(0,dialogs.Errors);Assert.IsTrue(await vm.FlushAsync());var doc=(await f.Planning.LoadAsync(f.Id)).Document!;Assert.IsEmpty(doc.References);Assert.IsNotNull(doc.ShotExternalLinks.Single().ProjectCopy);
        var restart=f.NewVm();await restart.LoadAsync(f.Id);Assert.IsNotNull(restart.AllProjectReferences.Single().PreviewPath);var resolved=await restart.ResolveOriginalAsync(restart.AllProjectReferences.Single());Assert.IsNotNull(resolved);Assert.AreEqual(Hash(selected),Hash(resolved));var owned=Path.Combine(output,"shot-owned-v1.ptplan");await restart.ExportProjectPackageAsync(owned);var seed=Path.Combine(output,"shot-missing-v1.ptplan");var state=await f.Planning.LoadAsync(f.Id);await PlanningProjectPackage.ExportAsync(seed,new(){Id=f.Id,Name="镜头独有副本闭环"},state with{Document=state.Document! with{ShotExternalLinks=[]}},await f.Shots.LoadAsync(f.Id),f.Planning.StorageRoot);
        var imported=await PlanningProjectPackage.ImportAsync(owned,Path.Combine(output,"isolated-import"));var importedDoc=(await new PlanningProjectStore(Path.Combine(imported.DataRoot,"planning")).LoadAsync(f.Id)).Document!;Assert.IsNull(importedDoc.ShotExternalLinks.Single().ReconnectedFile);Assert.IsNotNull(importedDoc.ShotExternalLinks.Single().ProjectCopy);Assert.AreEqual(Hash(selected),Hash(PlanningProjectCopyStorage.Resolve(importedDoc.ShotExternalLinks.Single().ProjectCopy!)));
        var view=new PlanningCenterView{DataContext=restart};view.Measure(new Size(1100,800));view.Arrange(new Rect(0,0,1100,800));view.UpdateLayout();view.DataContext=null;
        // Batch editor uses same storage lifecycle; later plain saves cannot resurrect old approval.
        var live=restart.Shots.Single();restart.StageShot(live with{References=[]});Assert.IsTrue(await restart.FlushAsync());Assert.IsEmpty((await f.Planning.LoadAsync(f.Id)).Document!.ShotExternalLinks);restart.DocumentCustomBody="编辑后正文";Assert.IsTrue(await restart.FlushAsync());Assert.IsEmpty((await f.Planning.LoadAsync(f.Id)).Document!.ShotExternalLinks);
        await File.WriteAllTextAsync(Path.Combine(output,"RESULT.json"),JsonSerializer.Serialize(new{project=f.Id,shot=shot.ShotId,reference=reference.ReferenceId,selected,selectedHash=Hash(selected),owned,ownedHash=Hash(owned),seed,seedHash=Hash(seed),isolatedRoot=imported.DataRoot,scope="Production choice command/real store/VM recreation and package import, NOT native process restart",copyPreservedAfterRemoval=File.Exists(resolved)},new JsonSerializerOptions{WriteIndented=true}));
    });
    [TestMethod]public Task LegacyRepairVisibleCancelAndFailureRetainOldReceiptThenRemoveAndSavePackage()=>RunSta(async()=>
    {
        EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);await f.Vm.NewShotCommand.ExecuteAsync(null);var shot=f.Vm.Shots.Single();var old=Path.Combine(f.Root,"old.png");var reference=new ProjectShotReference(Guid.NewGuid(),ShotReferenceKind.Pose,ExternalReference:old);await f.Shots.SaveAsync(shot with{References=[reference]});await f.Vm.LoadAsync(f.Id);var selected=Path.Combine(f.Root,"selected.png");await File.WriteAllBytesAsync(selected,PlanningRichFlowFixture.ReferencePng(0));var inspected=await PlanningExternalFile.InspectAsync(reference.ReferenceId,"reference",old,selected);await f.Vm.ReconnectExternalAsync(inspected,true);
        // Simulate an old mismatch by a foreign, pre-lifecycle bytes edit; do not use current public save API.
        var shotPath=Path.Combine(f.Shots.StorageRoot,f.Id.ToString("N")+".shots.json");var catalog=await f.Shots.LoadAsync(f.Id);await File.WriteAllTextAsync(shotPath,JsonSerializer.Serialize(catalog with{Shots=[catalog.Shots[0] with{References=[]}]}));var dialogs=new Decisions{Accept=false};var vm=new PlanningCenterViewModel(f.Projects,f.Bookings,dialogs,f.Shots,f.Planning);await vm.LoadAsync(f.Id);var issue=vm.ShotLinkIssues.Single();Assert.AreEqual(shot.ShotId,issue.ShotId);Assert.IsNotNull(issue.CopyPath);var plan=Path.Combine(f.Planning.StorageRoot,f.Id.ToString("N")+".planning.json");var before=Hash(plan);await vm.RepairShotLinkIssueAsync(issue,false);Assert.AreEqual(before,Hash(plan));
        dialogs.Accept=true;using(var held=new FileStream(plan,FileMode.Open,FileAccess.Read,FileShare.Read))await vm.RepairShotLinkIssueAsync(issue,false);Assert.AreEqual(before,Hash(plan));Assert.HasCount(1,dialogs.Errors);await vm.RepairShotLinkIssueAsync(issue,false);Assert.IsEmpty(vm.ShotLinkIssues);Assert.IsTrue(await vm.FlushAsync());var package=Path.Combine(f.Root,"fixed.ptplan");await vm.ExportProjectPackageAsync(package);PlanningProjectPackage.Validate(package);
    });
    sealed class Decisions:IDialogService
    {public string? File;public bool Accept;public List<string> Errors=[];public IReadOnlyList<string> ChooseFiles(string t,string f,bool m)=>File is null?[]:[File];public bool Confirm(string m,string t)=>Accept;public void ShowError(string m)=>Errors.Add(m);public void ShowInfo(string m){}public string? ChooseFolder(string t,string? i=null)=>null;public string? ChooseSaveFile(string t,string f,string e,string? n=null)=>null;public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string> ids)=>ids;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RawFileEntry? ChooseRawCandidate(IReadOnlyList<RawFileEntry> c)=>null;public bool ShowMediaDetails(MediaSelectionItem i,bool a)=>false;public void RevealFile(string p){}}
}
